//
//  Volumetric Lighting (God Rays)
//  Native Metal Shader - Atmospheric Effects
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float ray_intensity;
    float ray_samples;
    float light_x;
    float light_y;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float4 color = sourceTexture.sample(textureSampler, in.texCoord);

    // Light source position
    float2 lightPos = float2(uniforms.light_x, uniforms.light_y);

    // Direction from pixel to light
    float2 toLight = lightPos - in.texCoord;
    float dist = length(toLight);
    float2 rayDir = normalize(toLight);

    // Ray marching
    int samples = int(uniforms.ray_samples);
    float stepSize = dist / float(samples);

    float3 volumetric = float3(0.0);
    float totalOcclusion = 0.0;

    for (int i = 0; i < samples; i++) {
        float t = float(i) / float(samples);
        float2 samplePos = in.texCoord + rayDir * stepSize * float(i);

        // Sample the scene
        float4 sampleColor = sourceTexture.sample(textureSampler, samplePos);
        float luminance = dot(sampleColor.rgb, float3(0.299, 0.587, 0.114));

        // Occlusion (darker areas block light)
        float occlusion = 1.0 - luminance;
        totalOcclusion += occlusion;

        // Accumulate light with falloff
        float falloff = 1.0 - t;
        falloff *= falloff;

        // Light color (warm golden)
        float3 lightColor = float3(1.0, 0.95, 0.8);

        volumetric += lightColor * (1.0 - occlusion) * falloff;
    }

    volumetric /= float(samples);

    // Apply occlusion
    volumetric *= exp(-totalOcclusion * 0.1);

    // Distance falloff
    float distFalloff = 1.0 - smoothstep(0.0, 1.0, dist);
    volumetric *= distFalloff;

    // Add volumetric lighting
    color.rgb += volumetric * uniforms.ray_intensity;

    return color;
}

